import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt
RAD={'C':1.70,'N':1.55,'O':1.52,'S':1.80}
af=requests.get("https://alphafold.ebi.ac.uk/files/AF-P18009-F1-model_v6.pdb",timeout=120).text
A=[]
for l in af.split("\n"):
    if l.startswith("ATOM"):
        A.append(dict(name=l[12:16].strip(),resn=l[17:20].strip(),ri=int(l[22:26]),
                      el=(l[76:78].strip() or l[12:16].strip()[0]).upper(),
                      xyz=np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])])))
TIP={'ARG':['CZ','NH1','NH2','NE'],'GLN':['NE2','OE1','CD']}
tips={}
for a in A:
    if a['name'] in TIP.get(a['resn'],[]): tips.setdefault(a['ri'],[]).append(a['xyz'])
def d(i,j): return min(np.linalg.norm(x-y) for x in tips[i] for y in tips[j])

print("=== Distances between the sequence-motif candidate 'fingers' in the IpaH4.5 AlphaFold model ===")
print("Reference transition-state geometry: Gyp1 R343-Q378 = 3.75 A ; VirA R188-Q280 = 4.25 A")
pairs=[(41,146),(41,531),(41,567),(429,531),(429,567),(433,531),(433,567),(429,146),(433,146)]
rowsp=[]
for r_,q_ in pairs:
    dd=d(r_,q_); rowsp.append((f"R{r_}", f"Q{q_}", round(float(dd),1)))
    print(f"   R{r_:<4d} - Q{q_:<4d}  side-chain tip distance = {dd:6.1f} A   {'<-- compatible' if dd<8 else ''}")
dfp=pd.DataFrame(rowsp, columns=["Arg","Gln","dist_A"])

# ---- CA-based secondary structure estimate per region ----
ca={a['ri']:a['xyz'] for a in A if a['name']=='CA'}
ris=sorted(ca)
ss={}
for i in ris:
    if all((i+k) in ca for k in (1,2,3,4)):
        d13=np.linalg.norm(ca[i]-ca[i+3]); d14=np.linalg.norm(ca[i]-ca[i+4])
        ss[i]='H' if (4.5<d13<6.3 and 5.0<d14<6.8) else ('E' if d13>8.5 and d14>11.0 else 'C')
    else: ss[i]='C'
def comp(lo,hi):
    v=[ss[i] for i in ris if lo<=i<=hi]
    return {k: round(100*v.count(k)/len(v),1) for k in "HEC"}
print("\n=== Secondary-structure composition (CA-geometry estimate) by region of IpaH4.5 ===")
regions={"N-term 1-25":(1,25),"LRR 26-287":(26,287),"NEL 295-574":(295,574)}
for n,(lo,hi) in regions.items(): print(f"   {n:14s} {comp(lo,hi)}")
# reference folds
for pid,ch,nm in [("2G77","A","Gyp1 TBC domain"),("4FMB","A","VirA (bacterial TBC-like GAP)"),("3CVR","A","IpaH3 full length")]:
    t=requests.get(f"https://files.rcsb.org/download/{pid}.pdb",timeout=120).text
    c={}
    for l in t.split("\n"):
        if l.startswith("ATOM") and l[21]==ch and l[12:16].strip()=="CA":
            c[int(l[22:26])]=np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])])
    k=sorted(c); s=[]
    for i in k:
        if all((i+x) in c for x in (1,2,3,4)):
            d13=np.linalg.norm(c[i]-c[i+3]); d14=np.linalg.norm(c[i]-c[i+4])
            s.append('H' if (4.5<d13<6.3 and 5.0<d14<6.8) else ('E' if d13>8.5 and d14>11.0 else 'C'))
        else: s.append('C')
    print(f"   {nm:32s} {{'H': {round(100*s.count('H')/len(s),1)}, 'E': {round(100*s.count('E')/len(s),1)}, 'C': {round(100*s.count('C')/len(s),1)}}}  (n={len(s)})")

# ---------------- FIGURE ----------------
fig,axes=plt.subplots(1,3, figsize=(16,4.6))
ax=axes[0]
lbl=[f"{a}-{b}" for a,b in zip(dfp.Arg,dfp.Gln)]
ax.barh(lbl, dfp.dist_A, color="#7f8fa6")
ax.axvline(3.75, color="#c0392b", lw=2, label="Gyp1 R343-Q378 (3.8 A)")
ax.axvline(4.25, color="#e67e22", lw=2, ls="--", label="VirA R188-Q280 (4.3 A)")
ax.set_xlabel("side-chain tip distance in AlphaFold model (A)")
ax.set_title("Motif-derived Arg/Gln pairs in IpaH4.5\nare far apart in 3D", fontsize=10)
ax.legend(fontsize=7)

ax=axes[1]
cons={"R41":2,"Q146":2,"R429":12,"R433":12,"Q531":12,"Q567":12,"C379\n(NEL cat.)":12}
cols=["#95a5a6" if v<12 else "#2980b9" for v in cons.values()]
cols[-1]="#27ae60"
ax.bar(list(cons), list(cons.values()), color=cols)
